import { useTranslations } from "next-intl";
import Link from "next/link";
import { usePathname } from "next/navigation";

export default function Footer() {
  const t = useTranslations("footer");
  const pathname = usePathname();
  const locale = pathname.split("/")[1]; // "en" or "es"

  return (
    <footer className="w-full bg-gray-900 text-white py-12 px-8 mt-20">
      <div className="max-w-6xl mx-auto grid grid-cols-1 md:grid-cols-3 gap-10">

        {/* Brand */}
        <div>
          <h3 className="text-xl font-bold mb-4">GINKGO</h3>
          <p className="text-gray-400 text-sm">
            {t("rights")}
          </p>
        </div>

        {/* Navigation */}
        <div>
          <h4 className="font-semibold mb-4">{t("contact")}</h4>
          <ul className="space-y-2 text-gray-300">
            <li>
              <a href="mailto:info@ginkgo.mx" className="hover:text-white">
                info@ginkgo.mx
              </a>
            </li>
            <li>
              <a href="https://www.linkedin.com" className="hover:text-white">
                LinkedIn
              </a>
            </li>
            <li>
              <a href="https://www.instagram.com" className="hover:text-white">
                Instagram
              </a>
            </li>
          </ul>
        </div>

        {/* Legal */}
        <div>
          <h4 className="font-semibold mb-4">Legal</h4>
          <ul className="space-y-2 text-gray-300">
            <li>
              <Link href={`/${locale}/privacy`} className="hover:text-white">
                {t("privacy")}
              </Link>
            </li>
            <li>
              <Link href={`/${locale}/cookies`} className="hover:text-white">
                {t("cookies")}
              </Link>
            </li>
          </ul>
        </div>

      </div>
    </footer>
  );
}
